let POLICE_DIRECTORY=null;
let DIRECTORY_READY=false;
let DIRECTORY_ERROR="";
let DISTRIBUTION_POSTS=[],DISTRIBUTION_POSTS_VERSION=0,DISTRIBUTION_OPTIONS_CACHE="",DISTRIBUTION_OPTIONS_CACHE_VERSION=-1;
let RENDERED_DIRECTORY_KEY="",RENDERED_STATION_KEY="";

function directoryCounty(city){
  return POLICE_DIRECTORY&&POLICE_DIRECTORY.counties?POLICE_DIRECTORY.counties[city]||null:null;
}
function directoryDivision(city,name){
  const c=directoryCounty(city);
  return c&&Array.isArray(c.divisions)?c.divisions.find(d=>d.name===name)||null:null;
}
function fallbackDistributionPosts(){
  return [
    ...P.map(p=>({id:"taipei:"+p[0],label:"臺北市｜"+p[0],county:"臺北市",agency:"臺北市政府警察局",precinct:p[0],desc:p[1],vacancy:p[2],threshold:p[3]})),
    ...LOCAL_POLICE_AGENCIES.filter(x=>x[0]!=="臺北市").map(x=>({id:"local:"+x[0],label:x[1],county:x[0],agency:x[1],precinct:"",desc:"地方警察局分發；全國分局／派出所名錄載入後會細分到實際分局或警察所。",vacancy:x[2],threshold:x[3]}))
  ];
}
function divisionGameValues(city,name,index,total){
  const agency=agencyRecord(city)||[city,city+"警察局",20,65,false];
  if(city==="臺北市"){
    const p=P.find(x=>x[0]===name);
    if(p)return {vacancy:p[2],threshold:p[3]};
  }
  let hash=0;for(const ch of String(name))hash=(hash+ch.charCodeAt(0))%17;
  return {
    vacancy:Math.max(6,Math.round((agency[2]||20)*Math.max(.35,2/Math.max(2,total)))),
    threshold:Math.max(50,Math.min(82,(agency[3]||65)+(hash%7)-3))
  };
}
function rebuildDistributionPosts(){
  if(!DIRECTORY_READY){
    DISTRIBUTION_POSTS=fallbackDistributionPosts();
    DISTRIBUTION_POSTS_VERSION++;DISTRIBUTION_OPTIONS_CACHE_VERSION=-1;
    return;
  }
  const out=[];
  for(const agency of LOCAL_POLICE_AGENCIES){
    const city=agency[0],data=directoryCounty(city),divs=data&&Array.isArray(data.divisions)?data.divisions:[];
    if(divs.length){
      divs.forEach((d,i)=>{
        const g=divisionGameValues(city,d.name,i,divs.length);
        out.push({
          id:"dir:"+city+":"+d.name,
          label:city+"｜"+d.name,
          county:city,
          agency:data.agency||agency[1],
          precinct:d.name,
          desc:(d.stations?.length||0)+" 個分駐／派出／駐在所｜"+(d.address||""),
          vacancy:g.vacancy,
          threshold:g.threshold
        });
      });
    }else{
      out.push({id:"local:"+city,label:agency[1],county:city,agency:agency[1],precinct:"",desc:"目前來源未解析出分局層級，先以警察局分發。",vacancy:agency[2],threshold:agency[3]});
    }
  }
  DISTRIBUTION_POSTS=out;
  DISTRIBUTION_POSTS_VERSION++;DISTRIBUTION_OPTIONS_CACHE_VERSION=-1;
}
function distributionPost(id){return DISTRIBUTION_POSTS.find(x=>x.id===id)||null}
rebuildDistributionPosts();
