function stationRecords(){
  const d=directoryDivision(s&&s.county,s&&s.precinct);
  if(d&&Array.isArray(d.stations)&&d.stations.length)return d.stations;
  if(s&&s.county==="臺北市"&&STATIONS[s.precinct])return STATIONS[s.precinct].map(name=>({name,address:"",phone:""}));
  return [];
}
function stationList(){return stationRecords().map(x=>typeof x==="string"?x:x.name).filter(Boolean)}
function stationRecord(name){return stationRecords().find(x=>(typeof x==="string"?x:x.name)===name)||null}
function randomStation(){const a=stationList();return a.length?a[Math.floor(Math.random()*a.length)]:"轄內派出所"}
function stationFullName(name){return localPrefix()+name}
