  all.forEach(b=>{
    b.style.setProperty("display","none","important");
    b.disabled=true;
    b.style.pointerEvents="none";
    b.setAttribute("aria-hidden","true");
    b.classList.remove("primary-btn");
    b.classList.add("secondary-btn");
  });
  let active=null;
  if(!s.route||s.written===null||s.written<55)active=w;
  else if(s.physical===null||s.physical<55)active=p;
  else if(!s.training)active=tr;
  else active=next;
  if(active){
    active.style.setProperty("display","inline-flex","important");
    active.disabled=false;
    active.style.pointerEvents="auto";
    active.removeAttribute("aria-hidden");
    active.classList.remove("secondary-btn");
    active.classList.add("primary-btn");
  }
}
