async function loadPoliceDirectory(){
  try{
    const res=await fetch("police-directory.json",{cache:"default"});
    if(!res.ok)throw new Error("HTTP "+res.status);
    const data=await res.json();
    if(!data||!data.counties||!Object.keys(data.counties).length)throw new Error("資料尚未建立");
    POLICE_DIRECTORY=data;DIRECTORY_READY=true;DIRECTORY_ERROR="";
    rebuildDistributionPosts();
    if(s&&s.county&&!s.localAgency)s.localAgency=directoryCounty(s.county)?.agency||agencyRecord(s.county)?.[1]||"";
    if(s&&s.precinct){
      const has=directoryDivision(s.county,s.precinct);
      if(!has&&s.county!=="中央"&&s.county!=="臺北市"){s.precinct="";s.stationName="";s.unit="";s.unitName="";}
    }
    if(Array.isArray(s?.initialOffers)&&s.initialOffers.some(o=>o.stationName==="轄內派出所")){s.initialOffers=[];s.selectedUnit="";}
    if(Array.isArray(s?.rotationOffers)&&s.rotationOffers.some(o=>o.stationName==="轄內派出所")){s.rotationOffers=[];s.selectedUnit="";}
    if($("distribution")?.classList.contains("active"))dist();
    if($("unit")?.classList.contains("active"))units();
  }catch(err){
    DIRECTORY_ERROR=err&&err.message?err.message:String(err);
    console.warn("police directory load failed",err);
    if($("distribution")?.classList.contains("active"))renderNationalDirectory();
  }
}
