  if(s.retired){
    if($("dutySubtitle"))$("dutySubtitle").textContent="已退休｜"+(s.retirementReason||"退休")+"｜原職："+(s.lastActivePosition||"—");
    if($("nextDutyBtn"))$("nextDutyBtn").disabled=true;
