  const parts=detail.split(/[｜|]/).map(x=>x.trim()).filter(Boolean);
  const rolePart=parts.find(x=>!/(?:警察局|警政署|派出所|分駐所|駐在所|警察大學)/.test(x)&&role.test(x));
