  function pickRoleCase(rows,key){
    if(!rows.length)throw new Error("本職務題組尚未建立");
    const identity=rows.map(x=>x.roleCaseId||x[0]).join("|");
    let bag=roleCaseBags.get(key);
    if(!bag||bag.identity!==identity)bag={identity,left:[],last:-1};
    if(!bag.left.length){
      bag.left=rows.map((_,i)=>i);
      for(let i=bag.left.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[bag.left[i],bag.left[j]]=[bag.left[j],bag.left[i]];}
      if(bag.left.length>1&&bag.left.at(-1)===bag.last)[bag.left[0],bag.left[bag.left.length-1]]=[bag.left.at(-1),bag.left[0]];
    }
    const index=bag.left.pop();bag.last=index;roleCaseBags.set(key,bag);
    const original=rows[index],row=original.slice();row[2]=original[2].map(c=>c.slice());
    for(let i=row[2].length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[row[2][i],row[2][j]]=[row[2][j],row[2][i]];}
    row.analysis=original.analysis||"";row.roleCaseId=original.roleCaseId||original[0];return row;
  }
