    const latest=(s.appraisals||[])[0]?.grade;
    const ok=score>=50&&rewardsOutweighPenalties()&&(s.discipline||0)>=80&&latest!=="丙等";
    return {ok,score,latest:latest||"尚無",reward:rewardPoints(),penalty:penaltyPoints(),performance:performanceContribution(),appraisalPerformance:appraisalPerformance(),outcomePerformance:outcomePerformancePoints()};
  }
  function class1Eligibility(){
    const pos=/巡佐|小隊長|警務佐|教育班長|偵查佐/.test(positionName());
    const yrs=typeof serviceYearsExact==="function"?serviceYearsExact():Number(s.year||0);
    const ok=pos&&yrs>=10&&(s.seq10Days||0)>=1095&&recentTwoYearAppraisalOK()&&rewardsOutweighPenalties()&&s.age<56&&(s.fit||0)>=60&&(s.discipline||0)>=80;
    return {ok,yrs};
  }
  function class3Eligibility(){
    const criminal=/偵查佐|刑事小隊長/.test(positionName())||s.unit==="detective"||s.assignmentType==="detective";
    const yrs=typeof serviceYearsExact==="function"?serviceYearsExact():Number(s.year||0);
    const ok=criminal&&yrs>=6&&(s.seq10Days||0)>=1095&&recentTwoYearAppraisalOK()&&rewardsOutweighPenalties()&&s.age<56&&(s.fit||0)>=60&&(s.discipline||0)>=80;
    return {ok,yrs};
  }
  function class2Eligibility(){
    const exam=!!(s.promotionExamPassed||s.thirdGradeUpgradePassed);
    const degree=/大學|研究所/.test(String(s.education||""))||s.route==="tpa"||s.promotionTrainingPassed;
    const ok=exam&&degree&&rewardsOutweighPenalties()&&s.age<56&&(s.fit||0)>=60&&(s.discipline||0)>=80;
    return {ok,exam,degree};
  }
  function policeMonitorTrainingEligibility(){
    const routeOK=["cpu","g3"].includes(s.route)||!!(s.promotionExamPassed||s.thirdGradeUpgradePassed);
    const rankOK=s.officialRank==="警正一階";
    const seqOK=currentSequenceNo()===4;
    const started=parseLocalDateTime(s.positionStartDate||s.joinDate||s.simDate);
    const years=Math.max(0,(simNow().getTime()-started.getTime())/86400000/365.2425);
    const requiredYears=s.route==="cpu"?6:3;
    const tenureOK=years>=requiredYears;
    const annual=annualAppraisals(3);
    const gradeOK=annual.filter(x=>x.grade==="甲等").length>=2&&annual.every(x=>x.grade==="甲等"||x.grade==="乙等");
    const disciplineOK=(s.discipline||0)>=80;
    const ok=seqOK&&rankOK&&routeOK&&tenureOK&&gradeOK&&disciplineOK&&!s.policeMonitorTrainingPassed;
    return {ok,seqOK,rankOK,routeOK,years,requiredYears,tenureOK,annual,gradeOK,disciplineOK,passed:!!s.policeMonitorTrainingPassed};
  }
  function renderPoliceMonitorTraining(){
    const panel=$("policeMonitorTrainingPanel");if(!panel)return;
    const e=policeMonitorTrainingEligibility(),seq=currentSequenceNo();
    panel.style.display=seq<=5?"":"none";
    const grades=e.annual.map(x=>x.grade).join("／")||"尚無正式年度考績";
    const missing=[];
    if(!e.seqOK)missing.push("須任第4序列職務");
    if(!e.rankOK)missing.push("官階須為警正一階");
    if(!e.routeOK)missing.push("須具警大或三等考試等相應資格");
    if(!e.tenureOK)missing.push("職務年資須滿"+e.requiredYears+"年（目前"+e.years.toFixed(1)+"年）");
    if(!e.gradeOK)missing.push("近三年年終考績須至少2甲、其餘乙等以上（目前"+grades+"）");
    if(!e.disciplineOK)missing.push("獎懲操行分須達80分（目前"+(s.discipline||0)+"分）");
    const last=String(s.policeMonitorTrainingLastResult||"");
    let status=e.passed
      ?last||"警監班訓練已完成；符合條件後可申請第3序列職務甄審。"
      :last+(e.ok?"":"｜目前資格未達："+missing.join("；"));
    if(!status)status=e.ok
      ?"參訓資格符合。按下「申請並參加訓練」後，模擬進行28天訓練並在此顯示結果。"
      :"尚未符合參訓資格："+missing.join("；");
    $("policeMonitorTrainingStatus").textContent=status;
    $("policeMonitorTrainingBtn").disabled=!e.ok;
    $("policeMonitorTrainingBtn").textContent=e.passed?"已完成訓練":e.ok?"申請並參加訓練":"參訓資格未達";
  }
  function takePoliceMonitorTraining(){
    const e=policeMonitorTrainingEligibility();
    if(e.passed){$("policeMonitorTrainingStatus").textContent=s.policeMonitorTrainingLastResult||"警監班訓練已完成。";return}
    if(!e.ok){renderPoliceMonitorTraining();return}
    const score=Math.round(Math.min(100,35+(s.law||0)*.2+(s.knowledge||0)*.15+(s.service||0)*.1+(promotionScore())*.2+Math.random()*15));
    s.policeMonitorTrainingAttempts=(s.policeMonitorTrainingAttempts||0)+1;
    advanceDays(28);
    if(score>=65){
      s.policeMonitorTrainingPassed=true;
      s.policeMonitorTrainingLastResult="警監班訓練完成，模擬成績"+score+"分，及格；已解鎖第3序列職務甄審資格，仍須依缺額與資績甄審。";
      rec("警正升警監官等訓練","警監班結訓及格｜模擬成績 "+score);
    }else{
      s.policeMonitorTrainingLastResult="本次警監班訓練未通過，模擬成績"+score+"分；可繼續累積法學、勤務資績後再申請。";
      rec("警正升警監官等訓練","未及格｜模擬成績 "+score);
    }
    save();render();
  }
  function promotionExamEligibility(){
