  function recordMixedQuizAnswer(q,i,resultId){
    const accepted=q[8]?.accepted||[q[2]];
    const correct=accepted.includes(i);
    s.quizTotal=(s.quizTotal||0)+1;
    if(correct){s.quizCorrect=(s.quizCorrect||0)+1;s.knowledge=(s.knowledge||0)+3}
    const correctText=accepted.map(n=>String.fromCharCode(65+n)+". "+q[1][n]).join(" 或 ");
    fb(resultId,(q[8]?.historical?q[3]+"｜":"")+(correct?"答對了，知識 +3。"+(q[8]?.historical?"官方答案："+correctText+"。":""):"答錯了，正確答案是 "+correctText+"。")+q[4],correct);
    const box=$(resultId);
    if(box&&q[5]){
      const prefix=document.createElement("span");
      prefix.textContent=" 資料來源：";
      const link=document.createElement("a");
      link.href=q[5];link.target="_blank";link.rel="noopener noreferrer";link.textContent=q[6]||"官方法規／考試資料";
      box.append(prefix,link);
    }
    if(box&&q[8]?.historical){
      const paper=q[8].item.paper;
      const original=document.createElement("a");
      original.href=paper.questionUrl;original.target="_blank";original.rel="noopener noreferrer";original.textContent="｜完整試題 PDF";
      box.append(original);
      if(paper.correctionUrl&&paper.answerUrl){
        const standard=document.createElement("a");standard.href=paper.answerUrl;standard.target="_blank";standard.rel="noopener noreferrer";standard.textContent="｜原標準答案";box.append(standard);
      }
      if(q[8].declaration){
        const details=document.createElement("details"),summary=document.createElement("summary"),text=document.createElement("p");
        summary.textContent="考選部資料宣示";text.textContent=q[8].declaration;details.append(summary,text);box.append(details);
      }
      window.policeHistoricalQuestions?.record(q,correct);
    }
    const chip=$("quizChip");
    if(chip)chip.textContent="測驗 "+(s.quizCorrect||0)+"/"+(s.quizTotal||0);
    return correct;
  }
  function showMixedQuiz(caseId,choicesId,q,attribute,handler){
    const tag=document.createElement("span"),question=document.createElement("b");
    tag.className="tag";tag.textContent=q[3];question.textContent=q[0];question.style.whiteSpace="pre-line";
    $(caseId).replaceChildren(tag,document.createElement("br"),question);
    $(choicesId).replaceChildren();
    q[1].forEach((choice,i)=>{
      const card=document.createElement("button"),label=document.createElement("strong");
      card.type="button";card.className="action-card";card.setAttribute(attribute,String(i));
      label.textContent=String.fromCharCode(65+i)+". "+choice;card.append(label);card.onclick=()=>handler(i);$(choicesId).append(card);
    });
  }
  function requestMixedQuiz(caseId,choicesId,resultId,valid,ready){
    const fallback=()=>quizzes[Math.floor(Math.random()*quizzes.length)];
    if(!window.policeHistoricalQuestions){ready(fallback());return}
    $(caseId).textContent="正在抽取歷屆特考題目…";$(choicesId).replaceChildren();
    $(choicesId).setAttribute("aria-busy","true");
    let finished=false;
    const finish=(q,failed=false)=>{
      if(finished)return;finished=true;clearTimeout(timeout);
      if(!valid())return;
      $(choicesId).setAttribute("aria-busy","false");ready(q);
      if(failed)$(resultId).textContent="歷屆題庫暫時無法載入，先練基礎題；換題時會再試。";
    };
    const timeout=setTimeout(()=>finish(fallback(),true),8000);
    Promise.resolve().then(()=>window.policeHistoricalQuestions.next()).then(q=>finish(q),()=>finish(fallback(),true));
  }

