  function clearTopicQuizTimer(){
    if(topicQuizAdvanceTimer){clearTimeout(topicQuizAdvanceTimer);topicQuizAdvanceTimer=null}
  }
  function openTopicQuiz(topicId){
    if(!systemTopicQuizzes[topicId])return;
    clearTopicQuizTimer();
    if(quizAdvanceTimer){clearTimeout(quizAdvanceTimer);quizAdvanceTimer=null}
    topicQuizRun={topicId,index:0,answers:[],complete:false};
    $("topicQuizTitle").textContent=systemTopics[topicId][0];
    $("topicQuizResult").replaceChildren();$("topicQuizResult").className="feedback";
    showTopicQuizQuestion();
    const dialog=$("topicQuizDialog");
    if(!dialog.open){
      if(typeof dialog.showModal==="function")dialog.showModal();
      else dialog.setAttribute("open","");
    }
    document.body.classList.add("topic-quiz-open");
    $("topicQuizCloseBtn").focus();
  }
  function closeTopicQuiz(){
    clearTopicQuizTimer();
    const topicId=topicQuizRun&&topicQuizRun.topicId,dialog=$("topicQuizDialog");
    if(typeof dialog.close==="function")dialog.close();else dialog.removeAttribute("open");
    document.body.classList.remove("topic-quiz-open");
    topicQuizRun=null;
    const card=$("systemKnowledge").querySelector('[data-know="'+topicId+'"]');
    if(card)card.focus();
  }
  function showTopicQuizQuestion(){
    if(!topicQuizRun)return;
    const run=topicQuizRun,pool=systemTopicQuizzes[run.topicId],q=pool[run.index];
    $("topicQuizProgress").textContent="主題測驗 · 第 "+(run.index+1)+" / "+pool.length+" 題";
    $("topicQuizQuestion").textContent=q[0];
    $("topicQuizChoices").replaceChildren();
    q[1].forEach((text,i)=>{
      const button=document.createElement("button");button.type="button";button.className="topic-answer";button.dataset.topicAnswer=i;
      const letter=document.createElement("span");letter.className="topic-answer-letter";letter.textContent=String.fromCharCode(65+i);
      const label=document.createElement("span");label.textContent=text;
      button.append(letter,label);button.onclick=()=>answerTopicQuiz(i);$("topicQuizChoices").append(button);
    });
    $("topicQuizNextBtn").hidden=true;
    $("topicQuizStatus").textContent=run.answers.length?"繼續作答；下方保留上一題解析。":"選一個答案，即可查看解析。";
  }
  function answerTopicQuiz(i){
    const run=topicQuizRun;
    if(!run||run.complete||run.answers.length>run.index)return;
    const q=systemTopicQuizzes[run.topicId][run.index];
    if(!Number.isInteger(i)||!q[1][i])return;
    const correct=recordMixedQuizAnswer(q,i,"topicQuizResult");
    run.answers.push({choice:i,correct});
    const result=$("topicQuizResult");
    const heading=document.createElement("p");heading.className="topic-analysis-question";heading.textContent="第 "+(run.index+1)+" 題解析："+q[0];result.prepend(heading);
    const selected=document.createElement("p");selected.textContent="你的答案："+String.fromCharCode(65+i)+". "+q[1][i]+"。";
    const answer=document.createElement("p");answer.textContent="正確答案："+String.fromCharCode(65+q[2])+". "+q[1][q[2]]+"。";
    const reasoning=document.createElement("p");reasoning.textContent="選項分析："+q[7][i];
    const details=document.createElement("details"),summary=document.createElement("summary"),list=document.createElement("ul");
    summary.textContent="查看全部選項解析";
    q[7].forEach((reason,index)=>{const item=document.createElement("li");item.textContent=String.fromCharCode(65+index)+". "+reason;list.append(item)});
    details.append(summary,list);result.append(selected,answer,reasoning,details);
    $("topicQuizChoices").querySelectorAll("[data-topic-answer]").forEach(button=>{
      const n=Number(button.dataset.topicAnswer);button.disabled=true;
      if(n===q[2])button.classList.add("is-correct");
      if(n===i&&!correct)button.classList.add("is-wrong");
    });
    $("topicQuizNextBtn").hidden=false;
    $("topicQuizNextBtn").textContent=run.index+1<systemTopicQuizzes[run.topicId].length?"下一題":"查看成績";
    $("topicQuizStatus").textContent=run.index+1<systemTopicQuizzes[run.topicId].length?"稍後自動出下一題，解析會保留。":"稍後顯示本主題成績，解析會保留。";
    save();renderEnhancements();
    topicQuizAdvanceTimer=setTimeout(()=>{topicQuizAdvanceTimer=null;nextTopicQuiz()},1500);
  }
  function nextTopicQuiz(){
    clearTopicQuizTimer();
    const run=topicQuizRun;
    if(!run||!$("topicQuizDialog").open)return;
    if(run.complete){openTopicQuiz(run.topicId);return}
    if(run.answers.length<=run.index)return;
    const pool=systemTopicQuizzes[run.topicId],shouldFocusQuestion=$("topicQuizChoices").contains(document.activeElement)||document.activeElement===$("topicQuizNextBtn");
    if(run.index+1<pool.length){
      run.index++;showTopicQuizQuestion();
      if(shouldFocusQuestion)$("topicQuizQuestion").focus();
    }else{
      run.complete=true;
      const correct=run.answers.filter(x=>x.correct).length;
      $("topicQuizProgress").textContent="主題完成 · 答對 "+correct+" / "+pool.length+" 題";
      $("topicQuizStatus").textContent="本次正確率 "+Math.round(correct/pool.length*100)+"%。可查看解析或再練一次。";
      $("topicQuizNextBtn").hidden=false;$("topicQuizNextBtn").textContent="再練一次";
    }
  }

  function newQuiz(keepResult=false){
    if(quizAdvanceTimer){clearTimeout(quizAdvanceTimer);quizAdvanceTimer=null}
    const token=++quizRequest,owner=s;
    currentQuiz=null;quizAnswered=false;
    if(keepResult!==true){$("quizResult").textContent="";$("quizResult").className="feedback";}
    requestMixedQuiz("quizQuestion","quizChoices","quizResult",()=>token===quizRequest&&s===owner,q=>{
      currentQuiz=q;showMixedQuiz("quizQuestion","quizChoices",q,"data-q",answerQuiz);
    });
  }
  function answerQuiz(i){
    if(!currentQuiz||quizAnswered)return;
    quizAnswered=true;
    recordMixedQuizAnswer(currentQuiz,i,"quizResult");
    $("quizChoices").innerHTML="";save();renderEnhancements();
    quizAdvanceTimer=setTimeout(()=>{quizAdvanceTimer=null;newQuiz(true)},1500);
  }

  function appraisalScore(){
    let reward=s.commend*1.5+s.merit*4+s.greatMerit*10;
    let penalty=s.admonition*3+s.demerit*7+s.greatDemerit*18;
    return cl(Math.round(s.quality*.28+s.service*.22+s.discipline*.28+s.rep*.15+s.commandScore*.07+reward-penalty));
  }
  function appraisalGrade(sc){
    if(sc>=80&&s.greatDemerit===0)return"甲等";
    if(sc>=65)return"乙等";
    return"丙等";
  }
  function appraisalProgress(){
    const done=Math.max(0,(s.dutyCount||0)-(s.lastAppraisalDutyCount||0));
    const needed=Math.max(0,4-done);
    const d=simNow(),yr=d.getFullYear();
    const annualReady=d.getMonth()===11&&s.lastAppraisalYear!==yr;
    return {done,needed,annualReady,yr};
  }
  function appraisalPerformanceAward(grade,type){
    const points=grade==="甲等"?1:grade==="乙等"?.5:0;
    return type==="年度考績"?points*2:type==="階段考績"?points:0;
  }
  function appraisalPerformance(){
    // Derive this once from recorded results; rendering/loading cannot award it again.
    return (s.appraisals||[]).reduce((sum,x)=>sum+(x?appraisalPerformanceAward(x.grade,x.type):0),0);
  }
  function renderPerformance(){
    if(!$("commendStat"))return;
    let score=appraisalScore(),grade=appraisalGrade(score),p=appraisalProgress();
    $("commendStat").textContent=s.commend;$("meritStat").textContent=s.merit;$("admonitionStat").textContent=s.admonition;$("demeritStat").textContent=s.demerit;
    $("goodNoteStat").textContent=s.goodNotes;$("badNoteStat").textContent=s.badNotes;$("qualityStat").textContent=s.quality;$("serviceStat").textContent=s.service;$("disciplineStat").textContent=s.discipline;
    $("appraisalChip").textContent="目前預估："+grade+"（"+score+"）";$("disciplineChip").textContent="紀律分數："+s.discipline;

    let status="";
    if(!s.unit) status="尚未任職。";
    else if(p.annualReady) status="已進入12月，可直接辦理 <b>年度考績</b>。";
    else if(p.done>=4) status="已完成 "+p.done+" 件勤務，可立即辦理一次 <b>階段考績</b>。";
    else status="快速考績進度："+p.done+"/4 件勤務。再完成 <b>"+p.needed+"</b> 件即可辦理階段考績（約 "+(p.needed*30)+" 個遊戲日）。";

    const earned=appraisalPerformance(),nextType=p.annualReady?"年度考績":"階段考績";
    const expected=appraisalPerformanceAward(grade,nextType);
    const bonus="考績績效累積：<b>+"+earned.toFixed(1)+"</b>，已計入資績。<br>本次"+nextType+"預計 +"+expected.toFixed(1)+(!p.annualReady&&p.done<4?"（達勤務門檻並結算後發放）":"（結算後發放）")+"。";
    $("appraisalBox").innerHTML=s.unit?
      ("依目前資料預估 <b>"+grade+"</b>，綜合分數 "+score+"。<br>"+status+"<br>"+bonus+"<br><span class='muted'>階段甲等 +1、乙等 +0.5；年度甲等 +2、乙等 +1；丙等不加分。每4件勤務可辦一次階段考績；12月仍保留年度考績。此為遊戲績效機制，不等同官方考績或陞遷計分。</span>"):
      status;

    if($("closeYearBtn")){
      $("closeYearBtn").textContent=p.annualReady?"辦理年度考績":(p.done>=4?"辦理階段考績":"尚未達考績門檻");
      $("closeYearBtn").disabled=!p.annualReady&&p.done<4;
    }
    if($("appraisalProgress")){
      $("appraisalProgress").textContent=p.annualReady?"年度考績已開放":("階段考績 "+Math.min(p.done,4)+"/4 件");
    }
    $("disciplineHistory").innerHTML=s.disciplineLog.length?s.disciplineLog.slice(0,20).map(x=>'<div class="timeline-item"><b>'+x.type+'</b><span>'+x.reason+"｜"+x.date+'</span></div>').join(""):'<div class="empty-state">目前沒有獎懲紀錄。</div>';
  }
  function closeYear(){
    if(s.retired)return fb("appraisalBox","已退休，不再辦理現職考績。",0);
    if(!s.unit)return fb("appraisalBox","尚未任職，無法辦理考績。",0);
    const p=appraisalProgress();
    if(!p.annualReady&&p.done<4)return fb("appraisalBox","目前尚未達考績門檻，再完成 "+p.needed+" 件勤務即可辦理階段考績。",0);

    const scoreBefore=promotionScore(),performanceBefore=appraisalPerformance();
    let score=appraisalScore(),grade=appraisalGrade(score);
    const isAnnual=p.annualReady;
    const type=isAnnual?"年度考績":"階段考績";
    s.appraisalRounds=(s.appraisalRounds||0)+1;
    s.appraisals.unshift({year:p.yr-16,grade,score,type,round:s.appraisalRounds,date:rocDateTime()});
    s.lastAppraisalDutyCount=s.dutyCount||0;

    if(isAnnual){
      s.lastAppraisalYear=p.yr;
      if(grade==="甲等"){s.savings+=s.salary;addGood(2,"年終考績甲等");}
      else if(grade==="乙等"){s.savings+=Math.round(s.salary*.5);}
      else {s.reputation=cl(s.reputation-5);}
    }else{
      if(grade==="甲等"){addGood(1,"階段考績甲等");s.rep=cl(s.rep+2);}
      else if(grade==="乙等"){s.rep=cl(s.rep+1);}
      else {s.rep=cl(s.rep-2);}
    }

    const earned=appraisalPerformance()-performanceBefore;
    const feedback=type+"完成："+grade+"（"+score+"分）。考績績效 +"+earned.toFixed(1)+"。"+performanceProgressText(scoreBefore);
    rec(type,(p.yr-16)+"年 "+grade+"｜"+score+"分｜考績績效 +"+earned.toFixed(1)+performanceProgressText(scoreBefore));
    save();render();
    fb("appraisalBox",feedback,grade!=="丙等");
  }

