  function resolveCommand(i){
    if(commandCaseKey!==roleCaseOwnerKey()){syncRoleCaseQueues();return;}
    if(s.retired||!s.unit||!isSupervisor())return toast("目前無法執行主管決策");
    if(!commandActive)return;
