  }

  function latestAppraisalPoints(){
    const a=(s.appraisals||[]).filter(x=>x&&["甲等","乙等","丙等"].includes(x.grade)).slice(0,3);
    // Fill unrecorded slots with the existing neutral baseline, not a failing grade.
    return a.reduce((sum,x)=>sum+(x.grade==="甲等"?3:x.grade==="乙等"?2:0),0)+(3-a.length)*4/3;
  }
  function performanceContribution(){
    const points=(value,max)=>{
      const number=Number(value),stat=Number.isFinite(number)?cl(number):50;
      return Math.round(Math.max(0,stat-50)/50*max*10)/10;
    };
    const quality=points(s.quality,5),service=points(s.service,5),command=isSupervisor()?points(s.commandScore,2):0;
    return {quality,service,command,total:Math.round((quality+service+command)*10)/10};
  }
  function outcomePerformancePoints(){
    const value=Number(s.outcomePerformance);
    return Number.isFinite(value)?Math.max(0,value):0;
  }
  function awardOutcomePerformance(points){
    // Only call after a real case is resolved. Stats can cap while completed work still earns credit.
    s.outcomePerformance=Math.round((outcomePerformancePoints()+points)*10)/10;
    return points;
  }
  function performanceProgressText(before){
    const after=promotionScore(),difference=Math.round((after-before)*10)/10;
    return " 資績 "+before.toFixed(1)+" → "+after.toFixed(1)+"（"+(difference>=0?"+":"")+difference.toFixed(1)+"）。";
  }
  function promotionScore(){
    const edu={"高中畢業":8,"大學在學":10,"大學畢業":14,"研究所畢業":16}[s.education]||8;
    const exam=String(s.officialRank||"").startsWith("警正")?20:String(s.officialRank||"").startsWith("警佐")?14:0;
    const seniority=Math.min(20,Math.max(0,s.year||0)*2);
    const appraisal=Math.min(12,latestAppraisalPoints()*2);
    const reward=(s.commend||0)*0.1+(s.merit||0)*0.3+(s.greatMerit||0);
    const penalty=(s.admonition||0)*0.1+(s.demerit||0)*0.3+(s.greatDemerit||0);
    const discipline=Number(s.discipline),conduct=Math.max(0,Math.min(10,(Number.isFinite(discipline)?discipline:100)/10));
    const performance=performanceContribution().total;
    return Math.max(0,Math.round((edu+exam+seniority+appraisal+reward-penalty+conduct+performance+appraisalPerformance()+outcomePerformancePoints())*10)/10);
  }
