  function enhancedPromotion(){
    if(s.retired)return fb("careerMsg","已退休，不能再參加陞遷甄審。",0);
    if(!s.unit)return fb("careerMsg","尚未正式任職。",0);if((isOfficerTrack()||s.careerStage==="patrol_rotation")&&s.rotationEligible)return fb("careerMsg","目前已有職務輪調缺額待選，請先完成「職務輪調」再參加陞遷甄審。",0);
    const seq=currentSequenceNo(),nextSeq=seq>0?seq-1:null;
    if(nextSeq===null)return fb("careerMsg","已達最高職務層級。",1);
    if(seq===10&&nextSeq===9&&!patrolOfficerQualified()){
      return fb("careerMsg","巡佐／第十序列不能只靠資績直接升巡官。請先完成「警正官等資格」與「警大教育／訓練資格」，且績效、考績及獎懲須符合門檻。",0);
    }
    if(nextSeq===3&&!s.policeMonitorTrainingPassed)return fb("careerMsg","升任第3序列前，須先完成「警正升警監官等訓練／警監班」。請至「職務輪調」頁查看參訓資格。",0);
    const started=parseLocalDateTime(s.positionStartDate||s.joinDate||s.simDate);
    const positionDays=Math.max(0,Math.floor((simNow().getTime()-started.getTime())/86400000));
    const minPositionDays=seq>=10?730:548;
    if(positionDays<minPositionDays)return fb("careerMsg","目前職務年資尚未達甄審門檻；本序列至少需任職 "+Math.ceil(minPositionDays/30)+" 個月。",0);
    const score=promotionScore();
    const threshold={11:30,10:34,9:39,8:44,7:49,6:53,5:56,4:58,3:60,2:68,1:76}[seq]||45;
    const grade=s.appraisals?.[0]?.grade||appraisalGrade(appraisalScore());
    if(grade==="丙等"||s.greatDemerit>0)return fb("careerMsg","本次不具甄審條件：考績或重大懲處不符。",0);
    if(score<threshold)return fb("careerMsg","資績分數不足：目前 "+score+"，本次模擬甄審參考門檻 "+threshold+"。",0);
    const target=$("promotionTarget")?.value||targetPositions(nextSeq)[0];
    const vacancyChance=Math.max(.10,Math.min(nextSeq<=3?.55:.85,(nextSeq<=3?.25:.35)+score/(nextSeq<=3?320:250)));
    if(Math.random()>vacancyChance){
      s.promotionReviews.unshift({date:rocDateTime(),result:"未獲陞任",score,target,sequence:sequenceLabel(nextSeq)});
